import React, { createContext, useContext, useEffect, useState } from 'react';
import { ActivityIndicator, Button, FlatList, Linking, Modal, Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import type { Account as CustomerAccount, Bill, Customer, LedgerEntry, Notification as CustomerNotification, Payment, Reading, User } from '@solar-energy/shared';
import { ApiError, authApi, customerApi, tokenStore } from './src/api';

type Auth = { user: User | null; loading: boolean; login: (email: string, password: string) => Promise<void>; logout: () => Promise<void> };
const AuthContext = createContext<Auth | null>(null); const useAuth = () => { const v = useContext(AuthContext); if (!v) throw new Error('AuthProvider missing'); return v; };
function AuthProvider({ children }: { children: React.ReactNode }) { const [user, setUser] = useState<User | null>(null); const [loading, setLoading] = useState(true);
  useEffect(() => { tokenStore.get().then(token => token ? authApi.me().then(setUser).catch(async e => { if (e instanceof ApiError && e.status === 401) await tokenStore.clear(); }).finally(() => setLoading(false)) : setLoading(false)); }, []);
  const login = async (email: string, password: string) => { const result = await authApi.login(email, password); if (result.user.role !== 'CUSTOMER') throw new ApiError(403, 'Only customer accounts can use this app.'); await tokenStore.set(result.accessToken); setUser(result.user); };
  return <AuthContext.Provider value={{ user, loading, login, logout: async () => { await tokenStore.clear(); setUser(null); } }}>{children}</AuthContext.Provider>;
}
const Stack = createNativeStackNavigator(); const CustomerStack = createNativeStackNavigator(); const NotificationStack = createNativeStackNavigator<{ List: undefined; Detail: { notification: CustomerNotification } }>(); const BillStack = createNativeStackNavigator<{ List: undefined; Detail: { bill: Bill } }>(); const PaymentStack = createNativeStackNavigator<{ List: undefined; Detail: { payment: Payment } }>();
function Login() { const { login } = useAuth(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  return <SafeAreaView style={styles.screen}><Text style={styles.title}>Solar Energy</Text><Text style={styles.subtitle}>Customer portal</Text><TextInput style={styles.input} autoCapitalize="none" keyboardType="email-address" placeholder="Email" value={email} onChangeText={setEmail}/><TextInput style={styles.input} secureTextEntry placeholder="Password" value={password} onChangeText={setPassword}/>{error ? <Text style={styles.error}>{error}</Text> : null}<Button title={busy ? 'Signing in…' : 'Sign in'} disabled={busy} onPress={async () => { setError(''); setBusy(true); try { await login(email, password); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to sign in'); } finally { setBusy(false); } }}/></SafeAreaView>;
}
const format = (value: number | string) => `₦${Number(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const colors = { navy: '#10233f', blue: '#3b82f6', pale: '#edf5ff', bg: '#f7faff', muted: '#6b7b91', border: '#e4ebf4', green: '#138a63', red: '#c24156' };
function LegacyHome({ navigation }: { navigation: { navigate: (screen: string, params?: unknown) => void } }) { const { user } = useAuth(); const [profile, setProfile] = useState<Customer | null>(null); const [account, setAccount] = useState<CustomerAccount | null>(null); const [bills, setBills] = useState<Bill[]>([]); const [payments, setPayments] = useState<Payment[]>([]); const [readings, setReadings] = useState<Reading[]>([]); const [notifications, setNotifications] = useState<CustomerNotification[]>([]); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [errors, setErrors] = useState<Record<string, string>>({}); const [paying, setPaying] = useState(''); const load = async (refresh = false) => { refresh ? setRefreshing(true) : setLoading(true); setErrors({}); const results = await Promise.allSettled([customerApi.profile(), customerApi.account(), customerApi.bills(), customerApi.payments(), customerApi.readings(), customerApi.notifications()]); const keys = ['profile', 'account', 'bills', 'payments', 'readings', 'notifications']; const nextErrors: Record<string, string> = {}; results.forEach((result, index) => { if (result.status === 'rejected') nextErrors[keys[index]] = result.reason instanceof Error ? result.reason.message : 'Unable to load this section'; }); if (results[0].status === 'fulfilled') setProfile(results[0].value); if (results[1].status === 'fulfilled') setAccount(results[1].value); if (results[2].status === 'fulfilled') setBills(results[2].value.data); if (results[3].status === 'fulfilled') setPayments(results[3].value.data); if (results[4].status === 'fulfilled') setReadings(results[4].value.data); if (results[5].status === 'fulfilled') setNotifications(results[5].value); setErrors(nextErrors); setLoading(false); setRefreshing(false); }; useEffect(() => { void load(); }, []); const pay = async (billId: string) => { setPaying(billId); try { const result = await customerApi.initializePayment(billId); if (result.authorizationUrl) await Linking.openURL(result.authorizationUrl); } catch (e) { setErrors(current => ({ ...current, payment: e instanceof Error ? e.message : 'Unable to initialize payment' })); } finally { setPaying(''); } }; const latestByMeter = readings.reduce<Record<string, Reading>>((result, reading) => { if (!result[reading.meterId] || new Date(reading.readingAt) > new Date(result[reading.meterId].readingAt)) result[reading.meterId] = reading; return result; }, {}); const latestBill = bills[0]; const latestPayment = payments[0]; const latestNotifications = notifications.slice(0, 2); const go = (screen: string, params?: unknown) => navigation.navigate(screen, params); return <ScrollView contentContainerStyle={styles.content} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => void load(true)} />}><Text style={styles.title}>Welcome, {profile?.name ?? user?.name ?? 'Customer'}</Text>{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading your overview…</Text></View> : <><View style={styles.card}><Text style={styles.meta}>Customer</Text><Text style={styles.notificationTitle}>{profile?.customerNumber ?? 'Customer number unavailable'}</Text><Text>{profile?.status ?? 'Status unavailable'}</Text></View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Account balance</Text><Button title="Account" onPress={() => go('Account')}/></View>{errors.account ? <Text style={styles.error}>{errors.account}</Text> : account ? <Text style={styles.amount}>{format(account.balance)}</Text> : <Text style={styles.empty}>Balance unavailable.</Text>}</View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Meters</Text><Button title="Consumption" onPress={() => go('Consumption')}/></View>{errors.profile ? <Text style={styles.error}>{errors.profile}</Text> : profile?.meters?.length ? profile.meters.map(meter => <View style={styles.detail} key={meter.id}><Text style={styles.notificationTitle}>{meter.meterNumber}</Text><Text style={styles.meta}>{meter.meterType} · {meter.status}</Text></View>) : <Text style={styles.empty}>No meters assigned.</Text>}</View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Latest readings</Text><Button title="View all" onPress={() => go('Consumption')}/></View>{errors.readings ? <Text style={styles.error}>{errors.readings}</Text> : Object.values(latestByMeter).length ? Object.values(latestByMeter).map(reading => <View style={styles.detail} key={reading.id}><Text style={styles.notificationTitle}>{reading.meter?.meterNumber ?? 'Meter'}</Text><Text style={styles.meta}>Reading date: {new Date(reading.readingAt).toLocaleString()}</Text><Text>Current: {reading.currentReading ?? reading.reading}</Text><Text>Previous: {reading.previousReading == null ? 'First recorded reading' : `Previous: ${reading.previousReading}`}</Text><Text>Usage: {reading.consumptionKwh == null ? 'First recorded reading' : `${reading.consumptionKwh.toLocaleString()} kWh`} · {reading.source}</Text></View>) : <Text style={styles.empty}>No readings available.</Text>}</View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Recent bill</Text><Button title="Bills" onPress={() => go('Bills')}/></View>{errors.bills ? <Text style={styles.error}>{errors.bills}</Text> : latestBill ? <Pressable onPress={() => go('Bills', { screen: 'Detail', params: { bill: latestBill } })}><Text style={styles.notificationTitle}>{latestBill.billNumber}</Text><Text>{new Date(latestBill.billingPeriodStart).toLocaleDateString()} – {new Date(latestBill.billingPeriodEnd).toLocaleDateString()}</Text><Text>{format(latestBill.amount)} · {latestBill.status}{latestBill.dueDate ? ` · Due ${new Date(latestBill.dueDate).toLocaleDateString()}` : ''}</Text>{latestBill.status !== 'PAID' ? <Button title={paying === latestBill.id ? 'Starting…' : 'Pay bill'} disabled={paying === latestBill.id} onPress={() => void pay(latestBill.id)}/> : null}</Pressable> : <Text style={styles.empty}>No bills available.</Text>}</View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Recent payment</Text><Button title="Payments" onPress={() => go('Payments')}/></View>{errors.payments ? <Text style={styles.error}>{errors.payments}</Text> : latestPayment ? <Pressable onPress={() => go('Payments', { screen: 'Detail', params: { payment: latestPayment } })}><Text style={styles.notificationTitle}>{latestPayment.reference}</Text><Text>{format(latestPayment.amount)} · {latestPayment.currency ?? 'NGN'} · {latestPayment.status}</Text><Text style={styles.meta}>{new Date(latestPayment.paidAt ?? latestPayment.createdAt).toLocaleString()}</Text></Pressable> : <Text style={styles.empty}>No payments available.</Text>}</View><View style={styles.card}><View style={styles.row}><Text style={styles.section}>Notifications</Text><Button title="View all" onPress={() => go('Notifications')}/></View>{errors.notifications ? <Text style={styles.error}>{errors.notifications}</Text> : latestNotifications.length ? latestNotifications.map(notification => <Pressable key={notification.id} onPress={() => go('Notifications', { screen: 'Detail', params: { notification } })} style={notification.status !== 'READ' ? styles.unreadCard : undefined}><Text style={styles.notificationTitle}>{notification.title}</Text><Text style={styles.meta}>{notification.type} · {new Date(notification.createdAt).toLocaleString()}{notification.status !== 'READ' ? ' · UNREAD' : ''}</Text></Pressable>) : <Text style={styles.empty}>No notifications available.</Text>}</View><Text style={styles.section}>Quick navigation</Text><View style={styles.card}><Button title="Bills" onPress={() => go('Bills')}/><Button title="Payments" onPress={() => go('Payments')}/><Button title="Consumption" onPress={() => go('Consumption')}/><Button title="Account" onPress={() => go('Account')}/><Button title="Notifications" onPress={() => go('Notifications')}/></View>{errors.payment ? <Text style={styles.error}>{errors.payment}</Text> : null}</>}</ScrollView>; }
function Bills({ navigation }: { navigation: { navigate: (screen: 'Detail', params: { bill: Bill }) => void } }) { const [items, setItems] = useState<Bill[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const load = async () => { setLoading(true); setError(''); try { const result = await customerApi.bills(); setItems(result.data); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load bills'); } finally { setLoading(false); } }; useEffect(() => { void load(); }, []); return <View style={styles.content}><View style={styles.row}><Text style={styles.title}>Bills</Text><Button title="Retry" onPress={() => void load()} disabled={loading}/></View>{error ? <Text style={styles.error}>{error}</Text> : null}{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading bills…</Text></View> : items.length ? <FlatList data={items} keyExtractor={item => item.id} renderItem={({ item }) => <Pressable style={styles.card} onPress={() => navigation.navigate('Detail', { bill: item })}><Text style={styles.notificationTitle}>{item.billNumber}</Text><Text>{new Date(item.billingPeriodStart).toLocaleDateString()} – {new Date(item.billingPeriodEnd).toLocaleDateString()}</Text><Text>{format(item.amount)} · {item.status}{item.dueDate ? ` · Due ${new Date(item.dueDate).toLocaleDateString()}` : ''}</Text></Pressable>} /> : <Text style={styles.empty}>No bills available.</Text>}</View>; }
function BillDetail({ route, navigation }: { route: { params: { bill: Bill } }; navigation: { goBack: () => void } }) { const [bill, setBill] = useState<Bill | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [paying, setPaying] = useState(false); useEffect(() => { customerApi.bill(route.params.bill.id).then(setBill).catch(e => setError(e instanceof Error ? e.message : 'Unable to load bill')).finally(() => setLoading(false)); }, [route.params.bill.id]); const pay = async () => { if (!bill) return; setPaying(true); setError(''); try { const result = await customerApi.initializePayment(bill.id); if (result.authorizationUrl) await Linking.openURL(result.authorizationUrl); else setError('Payment initialized without a checkout URL.'); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to initialize payment'); } finally { setPaying(false); } }; return <ScrollView contentContainerStyle={styles.content}><Button title="Back" onPress={navigation.goBack}/>{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading bill…</Text></View> : error && !bill ? <><Text style={styles.error}>{error}</Text><Button title="Retry" onPress={() => { setLoading(true); setError(''); customerApi.bill(route.params.bill.id).then(setBill).catch(e => setError(e instanceof Error ? e.message : 'Unable to load bill')).finally(() => setLoading(false)); }}/></> : bill ? <><View style={styles.row}><Text style={styles.title}>{bill.billNumber}</Text><Text style={styles.status}>{bill.status}</Text></View>{error ? <Text style={styles.error}>{error}</Text> : null}{bill.status !== 'PAID' ? <Button title={paying ? 'Starting payment…' : 'Pay bill'} disabled={paying} onPress={() => void pay()}/> : null}<BillSection title="Bill"><Detail label="Billing period" value={`${new Date(bill.billingPeriodStart).toLocaleDateString()} – ${new Date(bill.billingPeriodEnd).toLocaleDateString()}`}/><Detail label="Created" value={new Date(bill.createdAt).toLocaleString()}/></BillSection><BillSection title="Financial details"><Detail label="Unit price" value={`${format(bill.unitPrice)} / kWh`}/><Detail label="Subtotal" value={format(bill.subtotal ?? bill.amount)}/><Detail label="Total amount" value={format(bill.amount)}/></BillSection><BillSection title="Consumption"><Detail label="Previous reading" value={bill.previousReading == null ? '—' : bill.previousReading.toLocaleString()}/><Detail label="Current reading" value={bill.currentReading == null ? '—' : bill.currentReading.toLocaleString()}/><Detail label="Consumption" value={`${bill.consumptionKwh.toLocaleString()} kWh`}/></BillSection><BillSection title="Meter"><Detail label="Meter number" value={bill.meter?.meterNumber ?? '—'}/><Detail label="Type" value={bill.meter?.meterType ?? '—'}/><Detail label="Status" value={bill.meter?.status ?? '—'}/></BillSection><BillSection title="Historical tariff"><Detail label="Name" value={bill.tariff?.name ?? '—'}/><Detail label="Unit price" value={`${format(bill.unitPrice)} / kWh`}/>{bill.tariff ? <Detail label="Effective period" value={`${new Date(bill.tariff.effectiveFrom).toLocaleDateString()} – ${bill.tariff.effectiveTo ? new Date(bill.tariff.effectiveTo).toLocaleDateString() : 'Open'}`}/> : null}</BillSection><BillSection title="Payment information"><Detail label="Due date" value={bill.dueDate ? new Date(bill.dueDate).toLocaleDateString() : '—'}/><Detail label="Paid date" value={bill.paidAt ? new Date(bill.paidAt).toLocaleString() : 'Not paid'}/></BillSection></> : null}</ScrollView>; }
function BillSection({ title, children }: { title: string; children: React.ReactNode }) { return <View style={styles.card}><Text style={styles.section}>{title}</Text>{children}</View>; }
function Detail({ label, value }: { label: string; value: string }) { return <View style={styles.detail}><Text style={styles.meta}>{label}</Text><Text>{value}</Text></View>; }
function ModernHome({ navigation }: { navigation: { navigate: (screen: string, params?: unknown) => void } }) {
  const { user, logout } = useAuth();
  const [profile, setProfile] = useState<Customer | null>(null);
  const [account, setAccount] = useState<CustomerAccount | null>(null);
  const [bills, setBills] = useState<Bill[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [notifications, setNotifications] = useState<CustomerNotification[]>([]);
  const [readings, setReadings] = useState<Reading[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [error, setError] = useState('');
  const load = async (refresh = false) => {
    refresh ? setRefreshing(true) : setLoading(true); setError('');
    const results = await Promise.allSettled([customerApi.profile(), customerApi.account(), customerApi.bills(), customerApi.readings(), customerApi.payments(), customerApi.notifications()]);
    if (results[0].status === 'fulfilled') setProfile(results[0].value);
    if (results[1].status === 'fulfilled') setAccount(results[1].value);
    if (results[2].status === 'fulfilled') setBills(results[2].value.data);
    if (results[3].status === 'fulfilled') setReadings(results[3].value.data);
    if (results[4].status === 'fulfilled') setPayments(results[4].value.data);
    if (results[5].status === 'fulfilled') setNotifications(results[5].value);
    if (results.some(result => result.status === 'rejected')) setError('Some account details are temporarily unavailable.');
    setLoading(false); setRefreshing(false);
  };
  useEffect(() => { void load(); }, []);
  const latestByMeter = readings.reduce<Record<string, Reading>>((result, reading) => { if (!result[reading.meterId] || new Date(reading.readingAt) > new Date(result[reading.meterId].readingAt)) result[reading.meterId] = reading; return result; }, {});
  const latestBill = bills[0]; const latestPayment = payments[0]; const latestNotification = notifications[0]; const unreadCount = notifications.filter(item => item.status !== 'READ').length; const name = profile?.name ?? user?.name ?? 'Customer';
  const go = (screen: string, params?: unknown) => { setMenuOpen(false); navigation.navigate(screen, params); };
  return <View style={styles.homeShell}><ScrollView contentContainerStyle={styles.content} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => void load(true)} />}>
    <View style={styles.homeHeader}><View><Text style={styles.brand}>Solar Energy</Text></View><View style={homeStyles.headerActions}><Pressable accessibilityLabel="Open profile" style={styles.menuButton} onPress={() => go('Profile')}><Ionicons name="person-outline" size={20} color={colors.navy} /></Pressable><Pressable accessibilityLabel="Open navigation menu" style={styles.menuButton} onPress={() => setMenuOpen(true)}><Ionicons name="menu-outline" size={24} color={colors.navy} /></Pressable></View></View>
    <View style={homeStyles.greetingBlock}><Text style={styles.greeting}>Good {new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 18 ? 'afternoon' : 'evening'}, {name}</Text><Text style={styles.meta}>Here's your solar energy overview</Text></View>
    {loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading your overview…</Text></View> : <>
      {error ? <Text style={styles.error}>{error}</Text> : null}
      <View style={styles.balanceCard}><View style={balanceStyles.heading}><View style={balanceStyles.icon}><Ionicons name="wallet-outline" size={21} color="#fff" /></View><Text style={balanceStyles.label}>Account Balance</Text></View><Text style={styles.balanceAmount}>{account ? format(account.balance) : '—'}</Text><Text style={balanceStyles.status}>{profile?.status ?? 'ACTIVE'}</Text><Text style={balanceStyles.supporting}>Your account is in good standing</Text></View>
      <View style={styles.identityRow}><View><Text style={styles.cardEyebrow}>Customer</Text><Text style={styles.identityName}>{name}</Text><Text style={styles.meta}>{profile?.customerNumber ?? 'Customer number unavailable'}</Text></View><Text style={styles.badge}>{profile?.status ?? 'UNKNOWN'}</Text></View>
      <Text style={styles.section}>Your meter</Text><View style={styles.card}>{profile?.meters?.length ? profile.meters.map(meter => <View style={styles.meterRow} key={meter.id}><View><Text style={styles.notificationTitle}>{meter.meterNumber}</Text><Text style={styles.meta}>{meter.meterType} · {meter.status}</Text></View><Text style={styles.badge}>{meter.status}</Text></View>) : <Text style={styles.empty}>No meters assigned.</Text>}</View>
      <Text style={styles.section}>Latest reading</Text><View style={styles.card}>{Object.values(latestByMeter).length ? Object.values(latestByMeter).map(reading => <View key={reading.id}><Text style={styles.readingValue}>{reading.currentReading ?? reading.reading} kWh</Text><Text style={styles.meta}>{new Date(reading.readingAt).toLocaleDateString()} · {reading.meter?.meterNumber ?? 'Meter'}</Text>{reading.previousReading != null || reading.consumptionKwh != null ? <Text style={styles.meta}>Previous {reading.previousReading ?? '—'} · Usage {reading.consumptionKwh == null ? '—' : `${reading.consumptionKwh.toLocaleString()} kWh`}</Text> : null}</View>) : <Text style={styles.empty}>No readings available.</Text>}</View>
      <Text style={styles.section}>Recent bill</Text><View style={styles.card}>{latestBill ? <Pressable onPress={() => go('Bills', { screen: 'Detail', params: { bill: latestBill } })}><View style={styles.row}><Text style={styles.notificationTitle}>{latestBill.billNumber}</Text><Text style={styles.badge}>{latestBill.status}</Text></View><Text style={styles.meta}>{new Date(latestBill.billingPeriodStart).toLocaleDateString()} – {new Date(latestBill.billingPeriodEnd).toLocaleDateString()}</Text><Text style={styles.billAmount}>{format(latestBill.amount)}</Text></Pressable> : <Text style={styles.empty}>No bills available.</Text>}</View>
      <Text style={styles.section}>Recent payment</Text><View style={styles.card}>{latestPayment ? <Pressable onPress={() => go('Payments', { screen: 'Detail', params: { payment: latestPayment } })}><View style={styles.row}><Text style={styles.notificationTitle}>{latestPayment.reference}</Text><Text style={styles.badge}>{latestPayment.status}</Text></View><Text style={styles.billAmount}>{currency(latestPayment.amount, latestPayment.currency)}</Text><Text style={styles.meta}>{new Date(latestPayment.paidAt ?? latestPayment.createdAt).toLocaleDateString()}</Text></Pressable> : <Text style={styles.empty}>No payments yet.</Text>}</View>
      <Text style={styles.section}>Notifications {unreadCount ? `· ${unreadCount} unread` : ''}</Text><View style={styles.card}>{latestNotification ? <Pressable onPress={() => go('Notifications', { screen: 'Detail', params: { notification: latestNotification } })}><Text style={styles.notificationTitle}>{latestNotification.title}</Text><Text style={styles.meta} numberOfLines={2}>{latestNotification.message}</Text><Text style={styles.meta}>{new Date(latestNotification.createdAt).toLocaleDateString()}</Text></Pressable> : <Text style={styles.empty}>No notifications yet.</Text>}</View>
      <Text style={styles.section}>Quick actions</Text><View style={quickStyles.grid}>{['Bills', 'Payments', 'Consumption', 'Account', 'Notifications', 'Profile'].map(item => <Pressable key={item} style={quickStyles.action} onPress={() => go(item)}><Ionicons name="arrow-forward-circle-outline" size={24} color={colors.blue}/><Text style={quickStyles.label}>{item}</Text></Pressable>)}</View>
    </>}</ScrollView><Modal visible={menuOpen} transparent animationType="fade" onRequestClose={() => setMenuOpen(false)}><Pressable style={styles.modalBackdrop} onPress={() => setMenuOpen(false)}><View style={styles.menuPanel}><Text style={styles.menuTitle}>Customer portal</Text>{['Home', 'Bills', 'Payments', 'Consumption', 'Notifications', 'Account', 'Profile'].map(item => <Pressable key={item} style={styles.menuItem} onPress={() => go(item)}><Ionicons name={item === 'Home' ? 'home-outline' : item === 'Bills' ? 'receipt-outline' : item === 'Payments' ? 'card-outline' : item === 'Consumption' ? 'speedometer-outline' : item === 'Notifications' ? 'notifications-outline' : item === 'Account' ? 'wallet-outline' : 'person-outline'} size={19} color={colors.blue} /><Text style={styles.menuItemText}>{item}</Text><Text style={styles.menuChevron}>›</Text></Pressable>)}<Pressable style={styles.menuItem} onPress={() => { setMenuOpen(false); void logout(); }}><Ionicons name="log-out-outline" size={19} color={colors.red} /><Text style={[styles.menuItemText, { color: colors.red }]}>Log out</Text></Pressable></View></Pressable></Modal></View>;
}
function BillNavigator() { return <BillStack.Navigator><BillStack.Screen name="List" component={Bills} options={{ title: 'Bills' }}/><BillStack.Screen name="Detail" component={BillDetail} options={{ title: 'Bill details' }}/></BillStack.Navigator>; }
const currency = (amount: number | string, code = 'NGN') => `${code === 'NGN' ? '₦' : `${code} `}${Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
function Payments({ navigation }: { navigation: { navigate: (screen: 'Detail', params: { payment: Payment }) => void } }) { const [items, setItems] = useState<Payment[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const load = async () => { setLoading(true); setError(''); try { const result = await customerApi.payments(); setItems(result.data); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load payments'); } finally { setLoading(false); } }; useEffect(() => { void load(); }, []); return <View style={styles.content}><View style={styles.row}><Text style={styles.title}>Payments</Text><Button title="Retry" onPress={() => void load()} disabled={loading}/></View>{error ? <Text style={styles.error}>{error}</Text> : null}{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading payments…</Text></View> : items.length ? <FlatList data={items} keyExtractor={item => item.id} renderItem={({ item }) => <Pressable style={styles.card} onPress={() => navigation.navigate('Detail', { payment: item })}><View style={styles.row}><Text style={styles.notificationTitle}>{item.reference}</Text><Text style={styles.status}>{item.status}</Text></View><Text>{currency(item.amount, item.currency)}</Text><Text style={styles.meta}>{item.method ?? 'Payment method not available'}{item.bill?.billNumber ? ` · ${item.bill.billNumber}` : ''}</Text><Text style={styles.meta}>Created {new Date(item.createdAt).toLocaleString()}{item.paidAt ? ` · Paid ${new Date(item.paidAt).toLocaleString()}` : ''}</Text></Pressable>} /> : <Text style={styles.empty}>No payments available.</Text>}</View>; }
function PaymentDetail({ route, navigation }: { route: { params: { payment: Payment } }; navigation: { goBack: () => void; navigate: (screen: 'Bills', params: { screen: 'Detail'; params: { bill: Bill } }) => void } }) { const [payment, setPayment] = useState<Payment | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const load = async () => { setLoading(true); setError(''); try { setPayment(await customerApi.payment(route.params.payment.id)); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load payment'); } finally { setLoading(false); } }; useEffect(() => { void load(); }, [route.params.payment.id]); return <ScrollView contentContainerStyle={styles.content}><Button title="Back" onPress={navigation.goBack}/>{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading payment…</Text></View> : error ? <><Text style={styles.error}>{error}</Text><Button title="Retry" onPress={() => void load()}/></> : payment ? <><View style={styles.row}><Text style={styles.title}>Payment</Text><Text style={styles.status}>{payment.status}</Text></View><PaymentSection title="Payment"><Detail label="Reference" value={payment.reference}/><Detail label="Amount" value={currency(payment.amount, payment.currency)}/><Detail label="Method" value={payment.method ?? 'Not available'}/><Detail label="Created" value={new Date(payment.createdAt).toLocaleString()}/><Detail label="Updated" value={payment.updatedAt ? new Date(payment.updatedAt).toLocaleString() : 'Not available'}/><Detail label="Paid/verified" value={payment.paidAt ? new Date(payment.paidAt).toLocaleString() : 'Not available'}/></PaymentSection><PaymentSection title="Customer"><Detail label="Name" value={payment.customer?.name ?? 'Not available'}/><Detail label="Customer number" value={payment.customer?.customerNumber ?? 'Not available'}/><Detail label="Email" value={payment.customer?.email ?? 'Not available'}/></PaymentSection><PaymentSection title="Related bill">{payment.bill ? <Pressable onPress={() => navigation.navigate('Bills', { screen: 'Detail', params: { bill: payment.bill as Bill } })}><Detail label="Bill number" value={payment.bill.billNumber}/><Detail label="Amount" value={currency(payment.bill.amount)}/><Detail label="Status" value={payment.bill.status}/><Detail label="Billing period" value={`${new Date(payment.bill.billingPeriodStart).toLocaleDateString()} – ${new Date(payment.bill.billingPeriodEnd).toLocaleDateString()}`}/><Detail label="Due date" value={payment.bill.dueDate ? new Date(payment.bill.dueDate).toLocaleDateString() : 'Not available'}/><Detail label="Paid date" value={payment.bill.paidAt ? new Date(payment.bill.paidAt).toLocaleString() : 'Not paid'}/><Text style={styles.link}>View bill details</Text></Pressable> : <Text style={styles.empty}>No bill linked to this payment.</Text>}</PaymentSection></> : null}</ScrollView>; }
function PaymentSection({ title, children }: { title: string; children: React.ReactNode }) { return <View style={styles.card}><Text style={styles.section}>{title}</Text>{children}</View>; }
function PaymentNavigator() { return <PaymentStack.Navigator><PaymentStack.Screen name="List" component={Payments} options={{ title: 'Payments' }}/><PaymentStack.Screen name="Detail" component={PaymentDetail} options={{ title: 'Payment details' }}/></PaymentStack.Navigator>; }
function Consumption() { const [items, setItems] = useState<Reading[]>([]); const [page, setPage] = useState(1); const [meta, setMeta] = useState<{ page: number; limit: number; total: number; totalPages: number } | undefined>(); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const pageSize = 10; const load = async (requestedPage: number) => { setLoading(true); setError(''); try { const result = await customerApi.readings(`?page=${requestedPage}&limit=${pageSize}`); setItems(result.data); setMeta(result.meta); setPage(result.meta?.page ?? requestedPage); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load consumption readings'); } finally { setLoading(false); } }; useEffect(() => { void load(1); }, []); const currentPage = meta?.page ?? page; const totalPages = meta?.totalPages ?? 1; const value = (reading: number | null | undefined) => reading == null ? '—' : reading.toLocaleString(); return <View style={styles.content}><View style={styles.row}><Text style={styles.title}>Consumption</Text><Button title="Refresh" onPress={() => void load(currentPage)} disabled={loading}/></View>{error ? <Text style={styles.error}>{error}</Text> : null}{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading readings…</Text></View> : items.length ? <><FlatList data={items} keyExtractor={item => item.id} renderItem={({ item }) => <View style={styles.card}><Text style={styles.notificationTitle}>Meter {item.meter?.meterNumber ?? 'Not available'}</Text><Text style={styles.meta}>Reading date: {new Date(item.readingAt).toLocaleString()}</Text><View style={styles.detail}><Text style={styles.meta}>Previous reading</Text><Text>{value(item.previousReading)}</Text></View><View style={styles.detail}><Text style={styles.meta}>Current reading</Text><Text>{value(item.currentReading)}</Text></View><View style={styles.detail}><Text style={styles.meta}>Usage</Text><Text style={styles.status}>{item.consumptionKwh == null ? 'First recorded reading' : `${value(item.consumptionKwh)} kWh`}</Text></View><Text style={styles.meta}>Source: {item.source}{item.meter?.meterType ? ` · Type: ${item.meter.meterType}` : ''}{item.meter?.status ? ` · Status: ${item.meter.status}` : ''}</Text></View>} /><View style={styles.pagination}><Text style={styles.meta}>Page {currentPage} of {totalPages}{meta ? ` · ${meta.total} readings` : ''}</Text><View style={styles.row}><Button title="Previous" onPress={() => void load(currentPage - 1)} disabled={loading || currentPage <= 1}/><Button title="Next" onPress={() => void load(currentPage + 1)} disabled={loading || currentPage >= totalPages}/></View></View></> : <Text style={styles.empty}>No consumption readings available.</Text>}</View>; }
function Notifications({ navigation }: { navigation: { navigate: (screen: 'Detail', params: { notification: CustomerNotification }) => void } }) { const [items, setItems] = useState<CustomerNotification[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [reading, setReading] = useState(''); const load = async () => { setLoading(true); setError(''); try { setItems(await customerApi.notifications()); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load notifications'); } finally { setLoading(false); } }; useEffect(() => { void load(); }, []); const markRead = async (id: string) => { setReading(id); setError(''); try { const updated = await customerApi.markNotificationRead(id); setItems(current => current.map(item => item.id === id ? { ...item, ...updated, status: 'READ' } : item)); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to mark notification as read'); } finally { setReading(''); } }; return <View style={styles.content}><View style={styles.row}><Text style={styles.title}>Notifications</Text><Button title="Retry" onPress={() => void load()} disabled={loading}/></View>{error ? <Text style={styles.error}>{error}</Text> : null}{loading ? <View style={styles.center}><ActivityIndicator/><Text>Loading notifications…</Text></View> : items.length === 0 ? <Text style={styles.empty}>No notifications yet.</Text> : <FlatList data={items} keyExtractor={item => item.id} renderItem={({ item }) => <Pressable onPress={() => navigation.navigate('Detail', { notification: item })} style={[styles.card, item.status !== 'READ' && styles.unreadCard]}><View style={styles.row}><Text style={styles.notificationTitle}>{item.title}</Text><Text style={item.status === 'READ' ? styles.read : styles.unread}>{item.status === 'READ' ? 'READ' : 'UNREAD'}</Text></View><Text>{item.message}</Text><Text style={styles.meta}>{item.type} · {new Date(item.createdAt).toLocaleString()}{item.sentAt ? ` · Sent ${new Date(item.sentAt).toLocaleString()}` : ''}</Text>{item.status !== 'READ' ? <Button title={reading === item.id ? 'Marking…' : 'Mark as read'} disabled={reading === item.id} onPress={() => void markRead(item.id)}/> : null}</Pressable>} />}</View>; }
function NotificationDetail({ route, navigation }: { route: { params: { notification: CustomerNotification } }; navigation: { goBack: () => void } }) { const [notification, setNotification] = useState(route.params.notification); const [error, setError] = useState(''); const [reading, setReading] = useState(false); const markRead = async () => { if (notification.status === 'READ') return; setReading(true); setError(''); try { const updated = await customerApi.markNotificationRead(notification.id); setNotification({ ...notification, ...updated, status: 'READ' }); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to mark notification as read'); } finally { setReading(false); } }; return <ScrollView contentContainerStyle={styles.content}><Button title="Back" onPress={navigation.goBack}/><Text style={styles.title}>{notification.title}</Text><Text style={styles.meta}>{notification.type} · {notification.status === 'READ' ? 'READ' : 'UNREAD'}</Text><Text style={styles.message}>{notification.message}</Text><Text style={styles.meta}>Created {new Date(notification.createdAt).toLocaleString()}</Text>{notification.sentAt ? <Text style={styles.meta}>Sent {new Date(notification.sentAt).toLocaleString()}</Text> : null}{error ? <Text style={styles.error}>{error}</Text> : null}{notification.status !== 'READ' ? <Button title={reading ? 'Marking…' : 'Mark as read'} disabled={reading} onPress={() => void markRead()}/> : null}</ScrollView>; }
function NotificationNavigator() { return <NotificationStack.Navigator><NotificationStack.Screen name="List" component={Notifications} options={{ title: 'Notifications' }}/><NotificationStack.Screen name="Detail" component={NotificationDetail} options={{ title: 'Notification' }}/></NotificationStack.Navigator>; }
function List<T>({ title, items, render }: { title: string; items: T[]; render: (item: T) => React.ReactNode }) { return <View style={styles.content}><Text style={styles.title}>{title}</Text><FlatList data={items} keyExtractor={(_, i) => String(i)} renderItem={({ item }) => <View style={styles.card}>{render(item)}</View>} ListEmptyComponent={<Text>Loading…</Text>} /></View>; }
function Account() { const [account, setAccount] = useState<CustomerAccount | null>(null); const [entries, setEntries] = useState<LedgerEntry[]>([]); const [accountLoading, setAccountLoading] = useState(true); const [ledgerLoading, setLedgerLoading] = useState(true); const [accountError, setAccountError] = useState(''); const [ledgerError, setLedgerError] = useState(''); const [page, setPage] = useState(1); const [meta, setMeta] = useState<{ page: number; limit: number; total: number; totalPages: number }>(); const [type, setType] = useState('ALL'); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const pageSize = 10; const types = ['ALL', 'CREDIT', 'PAYMENT', 'REFUND', 'DEBIT', 'CHARGE']; const loadAccount = async () => { setAccountLoading(true); setAccountError(''); try { setAccount(await customerApi.account()); } catch (e) { setAccountError(e instanceof Error ? e.message : 'Unable to load account'); } finally { setAccountLoading(false); } }; const loadLedger = async (requestedPage: number, selectedType = type, selectedFrom = from, selectedTo = to) => { setLedgerLoading(true); setLedgerError(''); const params = new URLSearchParams({ page: String(requestedPage), limit: String(pageSize) }); if (selectedType !== 'ALL') params.set('type', selectedType); if (selectedFrom) params.set('createdFrom', selectedFrom); if (selectedTo) params.set('createdTo', selectedTo); try { const result = await customerApi.ledger(`?${params.toString()}`); setEntries(result.data); setMeta(result.meta); setPage(result.meta?.page ?? requestedPage); } catch (e) { setLedgerError(e instanceof Error ? e.message : 'Unable to load ledger history'); } finally { setLedgerLoading(false); } }; useEffect(() => { void loadAccount(); void loadLedger(1); }, []); const currentPage = meta?.page ?? page; const totalPages = meta?.totalPages ?? 1; const refresh = () => { void loadAccount(); void loadLedger(currentPage); }; const clearFilters = () => { setType('ALL'); setFrom(''); setTo(''); void loadLedger(1, 'ALL', '', ''); }; return <ScrollView contentContainerStyle={styles.content}><View style={styles.row}><Text style={styles.title}>Account</Text><Button title="Refresh" onPress={refresh} disabled={accountLoading || ledgerLoading}/></View>{accountError ? <Text style={styles.error}>{accountError}</Text> : null}{accountLoading ? <View style={styles.card}><ActivityIndicator/><Text>Loading balance…</Text></View> : account ? <><View style={styles.card}><Text>Current balance</Text><Text style={styles.amount}>{format(account.balance)}</Text></View><View style={styles.card}><Text style={styles.section}>Account information</Text><Detail label="Created" value={new Date(account.createdAt).toLocaleString()}/><Detail label="Last updated" value={new Date(account.updatedAt).toLocaleString()}/></View></> : <View style={styles.card}><Text>Account information is unavailable.</Text><Button title="Retry" onPress={() => void loadAccount()}/></View>}<View style={styles.card}><Text style={styles.section}>Transaction history</Text><Text style={styles.meta}>Filter by transaction type</Text><View style={styles.filterRow}>{types.map(value => <Pressable key={value} onPress={() => { setType(value); void loadLedger(1, value); }} style={[styles.filterChip, type === value && styles.filterChipActive]}><Text style={type === value ? styles.filterTextActive : styles.filterText}>{value === 'ALL' ? 'All' : value}</Text></Pressable>)}</View><TextInput style={styles.input} placeholder="From date (YYYY-MM-DD)" value={from} onChangeText={setFrom}/><TextInput style={styles.input} placeholder="To date (YYYY-MM-DD)" value={to} onChangeText={setTo}/><Button title="Apply date filters" onPress={() => void loadLedger(1)} disabled={ledgerLoading}/><Button title="Clear filters" onPress={clearFilters} disabled={ledgerLoading}/></View>{ledgerError ? <View style={styles.card}><Text style={styles.error}>{ledgerError}</Text><Button title="Retry" onPress={() => void loadLedger(currentPage)} /></View> : null}{ledgerLoading ? <View style={styles.center}><ActivityIndicator/><Text>Loading transactions…</Text></View> : entries.length ? entries.map(entry => <View style={styles.card} key={entry.id}><View style={styles.row}><Text style={styles.notificationTitle}>{entry.type}</Text><Text style={['CREDIT', 'PAYMENT', 'REFUND'].includes(entry.type) ? styles.credit : styles.debit}>{['CREDIT', 'PAYMENT', 'REFUND'].includes(entry.type) ? 'CREDIT' : 'DEBIT'}</Text></View><Detail label="Amount" value={format(entry.amount)}/><Detail label="Balance before" value={format(entry.balanceBefore)}/><Detail label="Balance after" value={format(entry.balanceAfter)}/>{entry.description ? <Detail label="Description" value={entry.description}/> : null}{entry.reference ? <Detail label="Reference" value={entry.reference}/> : null}<Detail label="Date" value={new Date(entry.createdAt).toLocaleString()}/></View>) : <Text style={styles.empty}>No account activity is available yet.</Text>}{meta ? <View style={styles.card}><Text style={styles.meta}>Page {currentPage} of {totalPages} · {meta.total} transactions</Text><View style={styles.row}><Button title="Previous" onPress={() => void loadLedger(currentPage - 1)} disabled={ledgerLoading || currentPage <= 1}/><Button title="Next" onPress={() => void loadLedger(currentPage + 1)} disabled={ledgerLoading || currentPage >= totalPages}/></View></View> : null}</ScrollView>; }
function Profile() { const { user, logout } = useAuth(); const [profile, setProfile] = useState<Customer | null>(null); useEffect(() => { customerApi.profile().then(setProfile).catch(() => undefined); }, []); return <ScrollView contentContainerStyle={styles.content}><View style={profileStyles.hero}><View style={profileStyles.avatar}><Ionicons name="person-outline" size={30} color="#fff" /></View><Text style={styles.title}>{profile?.name ?? user?.name ?? 'Customer'}</Text><Text style={styles.meta}>{profile?.customerNumber ?? 'Customer number unavailable'}</Text><Text style={styles.badge}>{profile?.status ?? 'ACTIVE'}</Text></View><View style={styles.card}><Text style={styles.section}>Account information</Text><Detail label="Email" value={profile?.email ?? user?.email ?? 'Not available'}/><Detail label="Customer number" value={profile?.customerNumber ?? 'Not available'}/><Detail label="Status" value={profile?.status ?? 'Not available'}/>{profile?.meters?.map(meter => <Detail key={meter.id} label="Meter" value={`${meter.meterNumber} · ${meter.meterType}`}/>)}</View><Pressable style={profileStyles.logout} onPress={() => void logout()}><Ionicons name="log-out-outline" size={19} color={colors.red}/><Text style={profileStyles.logoutText}>Log out</Text></Pressable></ScrollView>; }
function CompactInfoCard({ icon, title, children, onPress, badge }: { icon: keyof typeof Ionicons.glyphMap; title: string; children: React.ReactNode; onPress?: () => void; badge?: string }) { return <Pressable style={homeRef.card} onPress={onPress}><View style={homeRef.iconCircle}><Ionicons name={icon} size={19} color={colors.blue} /></View><View style={homeRef.cardBody}><View style={homeRef.cardTitleRow}><Text style={homeRef.cardTitle}>{title}</Text>{badge ? <Text style={homeRef.badge}>{badge}</Text> : null}</View>{children}</View><Ionicons name="chevron-forward" size={18} color="#9aa9bb" /></Pressable>; }
function ReferenceHome({ navigation }: { navigation: { navigate: (screen: string, params?: unknown) => void } }) { const { user, logout } = useAuth(); const [profile, setProfile] = useState<Customer | null>(null); const [account, setAccount] = useState<CustomerAccount | null>(null); const [bills, setBills] = useState<Bill[]>([]); const [payments, setPayments] = useState<Payment[]>([]); const [readings, setReadings] = useState<Reading[]>([]); const [notifications, setNotifications] = useState<CustomerNotification[]>([]); const [loading, setLoading] = useState(true); const [menuOpen, setMenuOpen] = useState(false); const load = async () => { setLoading(true); const result = await Promise.allSettled([customerApi.profile(), customerApi.account(), customerApi.bills(), customerApi.payments(), customerApi.readings(), customerApi.notifications()]); if (result[0].status === 'fulfilled') setProfile(result[0].value); if (result[1].status === 'fulfilled') setAccount(result[1].value); if (result[2].status === 'fulfilled') setBills(result[2].value.data); if (result[3].status === 'fulfilled') setPayments(result[3].value.data); if (result[4].status === 'fulfilled') setReadings(result[4].value.data); if (result[5].status === 'fulfilled') setNotifications(result[5].value); setLoading(false); }; useEffect(() => { void load(); }, []); const name = profile?.name ?? user?.name ?? 'Customer'; const meter = profile?.meters?.[0]; const latestReading = readings[0]; const bill = bills[0]; const payment = payments[0]; const unread = notifications.filter(item => item.status !== 'READ').length; const go = (screen: string, params?: unknown) => { setMenuOpen(false); navigation.navigate(screen, params); }; const actions: Array<[string, keyof typeof Ionicons.glyphMap, string]> = [['Bills', 'receipt-outline', 'Bills'], ['Consumption', 'speedometer-outline', 'Usage'], ['Payments', 'card-outline', 'Payments'], ['Account', 'wallet-outline', 'Account'], ['Notifications', 'notifications-outline', 'Notifications'], ['Profile', 'person-outline', 'Profile']]; return <View style={homeRef.screen}><ScrollView contentContainerStyle={homeRef.content}>{loading ? <View style={styles.center}><ActivityIndicator /><Text style={styles.meta}>Loading your overview…</Text></View> : <><View style={homeRef.topbar}><Text style={styles.brand}>Solar Energy</Text><View style={homeRef.topActions}><Pressable style={styles.menuButton} onPress={() => go('Profile')}><Ionicons name="person-outline" size={19} color={colors.navy} /></Pressable><Pressable style={styles.menuButton} onPress={() => setMenuOpen(true)}><Ionicons name="menu-outline" size={23} color={colors.navy} /></Pressable></View></View><View style={homeRef.greeting}><Text style={homeRef.greetingTitle}>Good {new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 18 ? 'afternoon' : 'evening'}, {name}</Text><Text style={styles.meta}>Here's your solar energy overview</Text></View><View style={homeRef.balance}><View style={homeRef.balanceTop}><View style={homeRef.balanceIcon}><Ionicons name="wallet-outline" size={21} color="#fff" /></View><Text style={homeRef.balanceLabel}>ACCOUNT BALANCE</Text></View><Text style={homeRef.balanceAmount}>{account ? format(account.balance) : '—'}</Text><View style={homeRef.balanceBottom}><Text style={homeRef.active}> {profile?.status ?? 'ACTIVE'} </Text><Text style={homeRef.balanceHint}>Your account is in good standing</Text></View></View><CompactInfoCard icon="person-outline" title={name} badge={profile?.status ?? 'ACTIVE'} onPress={() => go('Profile')}><Text style={styles.meta}>{profile?.customerNumber ?? 'Customer number unavailable'}</Text></CompactInfoCard><CompactInfoCard icon="speedometer-outline" title="Your meter" onPress={() => go('Consumption')}><Text style={homeRef.primaryLine}>{meter?.meterNumber ?? 'No meter assigned'}</Text><Text style={styles.meta}>{meter ? `${meter.meterType} · ${meter.status}` : 'Meter information unavailable'}</Text></CompactInfoCard><CompactInfoCard icon="flash-outline" title="Latest reading" onPress={() => go('Consumption')}><Text style={homeRef.primaryLine}>{latestReading ? `${(latestReading.currentReading ?? latestReading.reading).toLocaleString()} kWh` : 'No readings available'}</Text><Text style={styles.meta}>{latestReading ? `${new Date(latestReading.readingAt).toLocaleDateString()} · Prev: ${latestReading.previousReading ?? '—'} · Usage: ${latestReading.consumptionKwh == null ? '—' : `${latestReading.consumptionKwh.toLocaleString()} kWh`}` : 'Reading data will appear here'}</Text></CompactInfoCard><CompactInfoCard icon="document-text-outline" title="Recent bill" badge={bill?.status} onPress={() => bill && go('Bills', { screen: 'Detail', params: { bill } })}><Text style={homeRef.primaryLine}>{bill?.billNumber ?? 'No bills available'}</Text><Text style={styles.meta}>{bill ? `${new Date(bill.billingPeriodStart).toLocaleDateString()} – ${new Date(bill.billingPeriodEnd).toLocaleDateString()}` : 'Your bills will appear here'}</Text>{bill ? <Text style={homeRef.amount}>{format(bill.amount)}</Text> : null}</CompactInfoCard><CompactInfoCard icon="card-outline" title="Recent payment" onPress={() => payment && go('Payments', { screen: 'Detail', params: { payment } })}>{payment ? <><Text style={homeRef.primaryLine}>{payment.reference}</Text><Text style={styles.meta}>{currency(payment.amount, payment.currency)} · {new Date(payment.paidAt ?? payment.createdAt).toLocaleDateString()}</Text></> : <><Text style={homeRef.primaryLine}>No payments yet</Text><Text style={styles.meta}>Your payment history will appear here once available.</Text></>}</CompactInfoCard><CompactInfoCard icon="notifications-outline" title="Notifications" badge={unread ? String(unread) : undefined} onPress={() => go('Notifications')}><Text style={homeRef.primaryLine}>{notifications[0]?.title ?? 'No notifications yet'}</Text><Text style={styles.meta} numberOfLines={1}>{notifications[0]?.message ?? 'You have no new notifications.'}</Text></CompactInfoCard><Text style={homeRef.section}>Quick Actions</Text><View style={homeRef.actions}>{actions.map(([screen, icon, label]) => <Pressable key={screen} style={homeRef.action} onPress={() => go(screen)}><View style={homeRef.actionIcon}><Ionicons name={icon} size={18} color={colors.blue} /></View><Text style={homeRef.actionLabel}>{label}</Text><Ionicons name="chevron-forward" size={14} color="#9aa9bb" /></Pressable>)}</View></>}</ScrollView><Modal visible={menuOpen} transparent animationType="fade" onRequestClose={() => setMenuOpen(false)}><Pressable style={styles.modalBackdrop} onPress={() => setMenuOpen(false)}><View style={styles.menuPanel}><Text style={styles.menuTitle}>Customer portal</Text>{['Home', 'Bills', 'Payments', 'Consumption', 'Notifications', 'Account', 'Profile'].map(item => <Pressable key={item} style={styles.menuItem} onPress={() => go(item)}><Text style={styles.menuItemText}>{item}</Text><Text style={styles.menuChevron}>›</Text></Pressable>)}<Pressable style={styles.menuItem} onPress={() => { setMenuOpen(false); void logout(); }}><Text style={[styles.menuItemText, { color: colors.red }]}>Log out</Text></Pressable></View></Pressable></Modal></View>; }
function CustomerTabs() { const screenOptions = { headerStyle: { backgroundColor: colors.bg }, headerTintColor: colors.navy, headerTitleStyle: { fontWeight: '700' as const, color: colors.navy }, headerShadowVisible: false }; return <CustomerStack.Navigator screenOptions={screenOptions}><CustomerStack.Screen name="Home" component={ReferenceHome} options={{ headerShown: false }}/><CustomerStack.Screen name="Bills" component={BillNavigator} options={{ headerShown: false }}/><CustomerStack.Screen name="Payments" component={PaymentNavigator} options={{ headerShown: false }}/><CustomerStack.Screen name="Consumption" component={Consumption}/><CustomerStack.Screen name="Notifications" component={NotificationNavigator} options={{ headerShown: false }}/><CustomerStack.Screen name="Account" component={Account}/><CustomerStack.Screen name="Profile" component={Profile}/></CustomerStack.Navigator>; }
function AppContent() { const { user, loading } = useAuth(); if (loading) return <View style={styles.center}><ActivityIndicator/></View>; return <NavigationContainer>{user?.role === 'CUSTOMER' ? <CustomerTabs/> : <Stack.Navigator><Stack.Screen name="Login" component={Login} options={{ headerShown: false }}/></Stack.Navigator>}</NavigationContainer>; }
export default function App() { return <SafeAreaProvider><AuthProvider><AppContent/></AuthProvider></SafeAreaProvider>; }
